{
  "assessment": "Cape Verde enjoys strong economic growth at 7.3% and low inflation, though public debt remains high at 100% of GDP. With elections scheduled for November 2026, maintaining domestic stability and addressing high unemployment (11.9%) are our primary priorities. We will focus on fiscal prudence, boosting infrastructure investment, and enhancing education and welfare to improve popular support and livelihoods.",
  "directives": [
    {
      "type": "set_tax",
      "target": null,
      "amount": 24.0,
      "sub": null,
      "order": "Maintain stable taxation at 24% of GDP to support public services while encouraging private sector growth."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 4.5,
      "sub": "health",
      "order": "Increase health spending to 4.5% of GDP."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 4.5,
      "sub": "education",
      "order": "Increase education spending to 4.5% of GDP."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 6.5,
      "sub": "welfare",
      "order": "Increase welfare spending to 6.5% of GDP to support vulnerable citizens and reduce unemployment hardship."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 4.0,
      "sub": "infrastructure",
      "order": "Increase infrastructure spending to 4.0% of GDP to stimulate employment and long-term economic capacity."
    },
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 1.0,
      "sub": null,
      "order": "Invest an extra 1% of GDP in infrastructure development."
    }
  ],
  "cables": [],
  "public_statement": "The Government of Cape Verde is committed to sustaining our robust economic growth while investing directly in the well-being of our citizens. Through targeted investments in health, education, infrastructure, and social welfare, we are building a more resilient, prosperous, and equitable future for all Cape Verdeans.",
  "standing_orders": [
    {
      "when": "unemployment_above:10",
      "do": {
        "type": "set_spending",
        "target": null,
        "amount": 4.5,
        "sub": "infrastructure",
        "order": "Maintain heightened infrastructure spending to boost employment."
      }
    }
  ],
  "detailed_report": "economy"
}
